'use strict';
const assert=require('assert/strict'),fs=require('fs'),os=require('os'),path=require('path'),crypto=require('crypto');const {buildBundle}=require('../scripts/linear-exit-atomic-writer-bundle');
const root=fs.mkdtempSync(path.join(os.tmpdir(),'atomic-bundle-test-'));
try{assert.throws(()=>buildBundle('relative'),/ABSOLUTE/);const dest=path.join(root,'bundle'),m=buildBundle(dest);assert.equal(m.functions.length,2);assert.equal(m.deployment_authorized,false);assert.equal(m.worker_required,true);assert.equal(m.sql_prerequisites_complete,false);assert.equal(m.hosted_baseline_observed_proven,false);assert.equal(m.sql_prerequisites.filter(x=>x.path.startsWith('supabase/migrations/')).length,7);assert.equal(m.release_extension_inventory,'docs/independence/LINEAR_EXIT_ADMISSION_RELEASE_EXTENSION_V1.json');for(const f of m.files){const b=fs.readFileSync(path.join(dest,f.path));assert.equal(crypto.createHash('sha256').update(b).digest('hex'),f.sha256);assert.equal(b.length,f.bytes);}const before=fs.readFileSync(path.join(dest,'manifest.json'));assert.throws(()=>buildBundle(dest),/EEXIST/);assert.deepEqual(fs.readFileSync(path.join(dest,'manifest.json')),before);for(const f of m.functions){assert.equal(f.verify_jwt,false);assert.equal(f.url_path,'/functions/v1/'+f.name);const source=fs.readFileSync(path.join(dest,f.index_path),'utf8');assert.ok(source.includes('Deno.serve('));assert.ok(!source.includes('file://'));}console.log('LINEAR_EXIT_ATOMIC_WRITER_BUNDLE_OK');}finally{fs.rmSync(root,{recursive:true,force:true});}
